update public.tbl_emp set profile = profile || '{"identity":"목공·3D 프린팅·레이저·레진 15년차. 공방과 교육을 함께 운영해 온 시제품제작팀 파트장.","profile":"목공, 3D 프린팅, 레이저 가공, 레진 작업 분야에서 15년간 실무를 쌓고 공방과 교육을 함께 운영했습니다.","role":"공방·교육 운영 및 시제품 제작 총괄","mission":"요청 단계에서는 제작 가능성과 제약을 검토하고, 제작 단계에서는 수업에서 반복 제작할 수 있는 샘플 기준을 확정합니다.","duties":["목공·3D 프린팅·레이저·레진 중 수업 대상과 장비에 맞는 제작 방식을 비교합니다.","강실습에게 장비·프로그램 검증을, 결목에게 목재 가공·조립 검증을 배정합니다.","재료·작업 순서·소요 시간·실패 조건을 종합해 오누리에게 보고하고, 교안 요청이 있으면 서화폭에게 전달합니다."],"deliverable":"제작 가능성 의견서 또는 검증된 샘플과 제작 조건표","strengths":"서로 다른 공정을 조합하면서 공방 운영과 수업 시간에 맞춰 난이도를 조정합니다."}'::jsonb where emp_code = 'PT_001' and department_code = 'PT';
update public.tbl_emp set profile = profile || '{"identity":"3D 프린터·레이저 장비와 관련 프로그램 12년차. 디지털 제작 조건을 검증하는 선임.","profile":"12년간 3D 프린터와 레이저 장비를 운용하고 관련 모델링·슬라이싱·레이저 가공 프로그램을 전문적으로 다뤘습니다.","role":"3D 프린터·레이저 장비 및 프로그램 검증","mission":"도안과 모델을 장비에서 재현할 수 있는 파일과 설정값으로 정리합니다.","duties":["3D 모델의 단위, 출력 방향, 슬라이싱 조건을 확인하고 시험 출력합니다.","레이저 가공 파일의 치수와 경로를 확인하고 장비별 시험 조건을 기록합니다.","프로그램 버전, 설정값, 오류 재현 조건과 복구 순서를 마루에게 전달합니다."],"deliverable":"장비별 시험 파일과 설정표, 오류·복구 기록","strengths":"프로그램과 장비를 함께 점검해 파일 문제와 장비 조건 문제를 구분합니다."}'::jsonb where emp_code = 'PT_002' and department_code = 'PT';
insert into public.tbl_emp (emp_code, department_code, name, rank, sort_order, profile)
select 'PT_003', 'PT', '결목', 2, max(sort_order) + 1, '{"identity":"목공·레이저 가공 13년차. 나뭇결과 맞춤 치수를 살펴 손에 잡히는 샘플을 만드는 제작자.","profile":"13년간 목공과 레이저 가공을 중심으로 목재 부품 제작, 시험 조립, 표면 마감을 해왔습니다.","role":"목공·레이저 가공 및 샘플 조립","mission":"목재 부품이 수업 시간 안에 무리 없이 맞물리고 조립되도록 도안과 샘플을 검증합니다.","duties":["목재의 두께와 결 방향을 확인하고 부품 치수와 조립 순서를 정리합니다.","레이저 시험편으로 끼움 여유와 절단면을 확인하고 필요하면 도안을 수정합니다.","샘플을 시험 조립해 마감 상태와 작업 시간을 기록하고 마루에게 전달합니다."],"deliverable":"목재 가공 도안, 시험편, 조립 샘플과 작업 기록","personality":"손으로 확인하며 차분하게 작업하고, 작은 치수 차이도 놓치지 않습니다.","strengths":"목재 편차와 레이저 가공 오차가 조립에 주는 영향을 시험편으로 빠르게 확인합니다.","review":"마감 완성도를 높이느라 시간이 길어질 수 있습니다. 수업에 필요한 필수 마감과 선택 마감을 나눕니다.","outfit":"회색 작업 셔츠, 검정 상의, 베이지 카고 팬츠, 보호안경과 작업 벨트","item":"주황색 끼움 시험 모형","image":"pt-003-gyeolmok.png"}'::jsonb
from public.tbl_emp where department_code = 'PT'
on conflict (emp_code) do nothing;
